import {expect} from '@playwright/test';
import {test,openTiming} from './sequential-timing-fixtures';
test('inspect literal preview on phone',async({page,timingClips})=>{
 await page.setViewportSize({width:390,height:740});await openTiming(page,await timingClips.create([{start:0,end:2,text:'café 🌓'},{start:3,end:5,text:'Untouched line'}]));
 await page.getByText('Replace lyric words',{exact:true}).click();await page.getByLabel('Literal text to replace',{exact:true}).fill('café 🌓');await page.getByLabel('Replacement lyric text',{exact:true}).fill('x'.repeat(160)+'<b>');
 await expect(page.locator('#words-replace-summary')).toContainText('1 match across 1 changed line');expect(await page.locator('#words-replace-preview b').count()).toBe(0);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
 await page.locator('.lyric-replace').screenshot({path:'/tmp/karaoke317-phone.png'});
});
